package com.gfilmes.license
import org.junit.Assert.*
import org.junit.Test
import java.security.KeyPairGenerator
import org.json.JSONObject
class LicenseCoreTest {
 private fun pair()=KeyPairGenerator.getInstance("RSA").apply{initialize(2048)}.generateKeyPair()
 @Test fun rfcBase64AndSignaturesRoundtrip(){for(s in listOf("","f","fo","foo","foobar","Gfilmes ação"))assertEquals(s,String(Crypto.decode(Crypto.encode(s.toByteArray()))));val p=pair();val j=Crypto.signJws(JSONObject().put("v",1),p.private);assertEquals(1,Crypto.verifyJws(j,p.public).getInt("v"));try{Crypto.verifyJws(j.dropLast(3)+"AAA",p.public);fail()}catch(_:Exception){}}
 @Test fun delegatedLicenseBindsDeviceAndCannotOutliveSubscription(){val root=pair();val issuer=pair();val id=Crypto.sha(issuer.public.encoded);val device="a".repeat(64);val authority=Crypto.signJws(JSONObject().put("v",1).put("kind","gfilmes-authority").put("issuerId",id).put("publicKey",Crypto.encode(issuer.public.encoded)).put("notBefore",1).put("expiresAt",MAX_LICENSE_MS*3).put("maxLicenseMs",MAX_LICENSE_MS),root.private)
  fun license(expiry:Long,subscription:Long)=JSONObject().put("authority",authority).put("license",Crypto.signJws(JSONObject().put("v",1).put("kind","gfilmes-offline-license").put("issuerId",id).put("licenseId","test").put("customerId","existing").put("username","fixture").put("deviceId",device).put("issuedAt",1000).put("expiresAt",expiry).put("subscriptionExpiresAt",subscription),issuer.private))
  val v=LicenseVerifier(root.public);assertEquals(5000,v.verify(license(5000,5000),device).expiresAt);for(e in listOf(license(MAX_LICENSE_MS+1001,MAX_LICENSE_MS*2),license(6000,5000))){try{v.verify(e,device);fail()}catch(_:IllegalArgumentException){}};try{v.verify(license(5000,5000),"b".repeat(64));fail()}catch(_:IllegalArgumentException){}}
 @Test fun monotonicClockSurvivesRebootRejectsRollbackAndExpires(){val start=ClockCheckpoint(100000,500000,1000,"1");val running=LicenseClock.advance(start,560000,61000,"1");assertEquals(160000,running.trustedMs);assertFalse(running.blocked);val reboot=LicenseClock.advance(running,620000,4000,"2");assertEquals(220000,reboot.trustedMs);assertFalse(reboot.blocked);assertTrue(LicenseClock.advance(reboot,600000,3000,"3").blocked);assertTrue(LicenseClock.advance(start,400000,40000,"1").blocked);val claims=LicenseClaims("x","a","u","d",1,220000,220000,1);assertEquals(0,LicenseClock.remaining(claims,reboot));assertEquals(120000,LicenseClock.remaining(claims,start))}
 @Test fun filtersAndPaginationNeverMixTypes(){val rows=(0 until 4000).map{CatalogRow("$it","Título $it",if(it%2==0)"movie" else "series",year=if(it%3==0)"2025" else "2024",genres=listOf(if(it%5==0)"Ação" else "Drama"))};val result=CatalogFilter.select(rows,"movie","título","Ação","2025","title_desc");assertTrue(result.isNotEmpty());assertTrue(result.all{it.kind=="movie"&&it.year=="2025"&&it.genres.contains("Ação")});val ids=mutableSetOf<String>();for(page in result.chunked(60)){assertTrue(page.size<=60);page.forEach{assertTrue(ids.add(it.id))}};assertEquals(result.size,ids.size)}
}
